exercise.referenceSolution:
struct Source { virtual int read() const = 0; virtual ~Source() = default; };
class Constant : public Source { int value_; public: explicit Constant(int x) : value_(x) {} int read() const override { return value_; } };
int twice(const Source& s) { return s.read()+s.read(); }
int solve(int a,int b) { Constant s{a}; return twice(s)+b; }

